    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>(((i * j + 2) % m)) / cast<int>(m);

    // Simple but reasonably fast schedule for initialization:
    Target target = get_jit_target_from_environment();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Row-parallel, vectorized over contiguous j dimension.
    init_A.compute_root()
          .parallel(i)
          .vectorize(j, vec);
    init_C.compute_root()
          .parallel(i)
          .vectorize(j, vec);

    init_A.realize(A, target);
    init_C.realize(C, target);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C_in  is N x N in C as C[i][j], map to Buffer C_in(j, i) => shape (n, n), used as input.
    // C_out is N x N output buffer, same layout; we print from this.
    // A     is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n).
    Halide::Buffer<num_t, 2> C_in(n, n);
    Halide::Buffer<num_t, 2> C_out(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide (fills C_in and A)
    init_array(n, m, &alpha, &beta, C_in, A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k iterates over M (first dimension of A, i.e., columns of the original A)
    RDom k(0, A.dim(0).extent(), "k");

    // Build the SYRK kernel in Halide
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // We express this as:
    //   C_new[i][j] = C[i][j]                                           if j > i
    //                = beta * C[i][j] + alpha * sum_k A[i][k] * A[j][k] if j <= i
    //
    // Remember mapping:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We'll compute a full N x N Func, and use select(j <= i, ..., orig)
    // to restrict updates to the lower triangle.
    Func syrk("syrk");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        cast<num_t>(beta_expr) * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for lower triangle.
    // For j > i, we add zero, so upper triangle remains just 'orig'.
    syrk(j, i) += select(j <= i,
                         cast<num_t>(alpha_expr) *
                             A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // -----------------------------
    // Schedule for high performance
    // -----------------------------
    //
    // Target-dependent vector width.
    Target target = get_jit_target_from_environment();
    const int vec = target.natural_vector_size(type_of<num_t>());

    // Tile sizes chosen to balance cache locality and parallel work.
    const int tile_j = vec * 8;  // tile along contiguous j dimension
    const int tile_i = 32;       // tile along i (rows)

    Var jo("jo"), io("io"), ji("ji"), ii("ii");

    // Compute result at root, tiled over (j,i).
    syrk.compute_root();

    // Pure definition: tile, parallelize outer tiles in i, vectorize across j.
    syrk
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i) // splits j,i and reorders to (ji,ii,jo,io)
        .parallel(io)                               // parallel over blocks of rows
        .vectorize(ji, vec);                        // SIMD across contiguous j

    // Update definition (reduction over k): use same tiling, keep k innermost
    // for good cache reuse along the contiguous A_param(k, ...) dimension.
    syrk.update()
        .tile(j, i, jo, io, ji, ii, tile_j, tile_i)
        // Loop order from outermost to innermost: io, jo, ii, ji, k
        .reorder(k, ji, ii, jo, io)
        .parallel(io)
        .vectorize(ji, vec);

    // Bind ImageParams (inputs remain read-only; result goes to a separate buffer)
    C_param.set(C_in);
    A_param.set(A);

    // Compile the kernel to machine code for the selected target
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C_out; C_in remains intact as input.
    syrk.realize(C_out, target);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
