    // C array A[i][j] is mapped to Buffer A(j, i) with shape (m, n).
    init_A(j, i) = cast<num_t>(((i * j + 1) % n)) / cast<num_t>(n);

    // Original C:
    // for (i = 0; i < n; i++)
    //   for (j = 0; j < n; j++)
    //     C[i][j] = ((i*j+2)%m) / m;
    //
    // C array C[i][j] is mapped to Buffer C(j, i) with shape (n, n).
    init_C(j, i) = cast<num_t>(((i * j + 2) % m)) / cast<num_t>(m);

    // Simple CPU schedule: each row (i) in parallel, j vectorized.
    init_A
        .compute_root()
        .parallel(i)
        .vectorize(j, VEC_WIDTH);

    init_C
        .compute_root()
        .parallel(i)
        .vectorize(j, VEC_WIDTH);

    init_A.realize(A);
    init_C.realize(C);
}

int main(int argc, char *argv[]) {
    // Problem size
    int n = N;
    int m = M;

    // Scalars
    num_t alpha;
    num_t beta;

    // Buffers:
    // C is N x N in C as C[i][j], map to Buffer C(j, i) => shape (n, n)
    // A is N x M in C as A[i][j], map to Buffer A(j, i) => shape (m, n)
    Halide::Buffer<num_t, 2> C(n, n);
    Halide::Buffer<num_t, 2> A(m, n);

    // ImageParams corresponding to C and A
    ImageParam C_param(type_of<num_t>(), 2, "C_param");
    ImageParam A_param(type_of<num_t>(), 2, "A_param");

    // Initialize data using Halide
    init_array(n, m, &alpha, &beta, C, A);

    // Bind ImageParams to the initialized buffers
    C_param.set(C);
    A_param.set(A);

    // Halide Vars and RDom
    Var i("i"), j("j");
    // k runs over the K dimension (the first dimension of A: size M)
    RDom k(0, A.dim(0).extent(), "k");

    // Build the SYRK kernel in Halide
    //
    // BLAS SYRK:
    //   C := alpha * A * A^T + beta * C
    //
    // Original C kernel:
    // for (i = 0; i < _PB_N; i++) {
    //   for (j = 0; j <= i; j++)
    //     C[i][j] *= beta;
    //   for (k = 0; k < _PB_M; k++) {
    //     for (j = 0; j <= i; j++)
    //       C[i][j] += alpha * A[i][k] * A[j][k];
    //   }
    // }
    //
    // Mapping from C layout to Halide buffers:
    //   C[i][j]   -> C_param(j, i)
    //   A[i][k]   -> A_param(k, i)
    //   A[j][k]   -> A_param(k, j)
    //
    // We compute a full N x N Func and use select(j <= i, ..., orig) so that:
    //   C_new[i][j] = C[i][j]  (upper triangle, j > i)
    //               = beta * C[i][j] + alpha * sum_k A[i][k] * A[j][k]  (j <= i)
    //
    // This preserves the original C semantics while allowing a
    // rectangular iteration domain that is easy for Halide to optimize.

    Func syrk("syrk");

    Expr alpha_expr = Expr(alpha);
    Expr beta_expr  = Expr(beta);

    // Original C value at (i,j)
    Expr orig = C_param(j, i);

    // Pure definition: scale lower triangle by beta, keep upper triangle unchanged.
    syrk(j, i) = select(j <= i,
                        cast<num_t>(beta_expr) * orig,
                        orig);

    // Reduction over k: add alpha * A[i][k] * A[j][k] for the lower triangle.
    syrk(j, i) += select(j <= i,
                         cast<num_t>(alpha_expr) *
                             A_param(k, i) * A_param(k, j),
                         cast<num_t>(0));

    // -------------------------
    // Scheduling for performance
    // -------------------------

    // Overall strategy:
    //  - Treat i (row index in original C) as the outer parallel dimension.
    //  - j is contiguous (x-dimension in the Halide buffer), so we vectorize it.
    //  - The reduction over k (columns of A) is tiled to improve cache reuse.
    //
    // Layout recap:
    //   C(j, i):  j contiguous   -> vectorize over j.
    //   A(k, i):  k contiguous   -> inner loops over k touch A’s columns
    //                               in a cache-friendly fashion.
    //
    // We structure the update as:
    //   for i (parallel)
    //     for k_outer
    //       for k_inner
    //         for j (vectorized)
    //           syrk(j, i) += ...
    //
    // This matches the BLAS-like “row of C” update:
    //   C[i, *] += alpha * A[i, k] * A[*, k]
    // where for each (i, k) we stream a row of A(*, k) and C(i,*).

    // Make the pure definition root, with i outer and j innermost.
    syrk
        .compute_root()
        .reorder(j, i)         // j innermost, i outermost
        .parallel(i)           // rows of C in parallel
        .vectorize(j, VEC_WIDTH);

    // Schedule the reduction update.
    RVar k_outer("k_outer"), k_inner("k_inner");
    syrk.update()
        // Tile the reduction over k to improve temporal locality in A and C.
        .split(k, k_outer, k_inner, K_TILE)
        // Order of loops from innermost to outermost: j, k_inner, k_outer, i
        .reorder(j, k_inner, k_outer, i)
        .parallel(i)           // different rows of C updated in parallel
        .vectorize(j, VEC_WIDTH);

    // Explicitly JIT-compile for the current host target (respects HL_JIT_TARGET).
    Target target = get_jit_target_from_environment();
    syrk.compile_jit(target);

    auto start = std::chrono::high_resolution_clock::now();

    // Run kernel: write result into C (in-place semantics w.r.t the original code)
    syrk.realize(C);

    auto end = std::chrono::high_resolution_clock::now();

    auto duration = std::chrono::duration<long double>(end - start);

    // Print results (similar spirit to the original print_array), guarded
    // the same way as in the GEMM example.
    using namespace std::string_literals;
    if (argc > 0 && argv[0] != ""s) {
        std::cerr << std::fixed << std::setprecision(2);
        for (int ii = 0; ii < n; ii++) {
            for (int jj = 0; jj < n; jj++) {
                // C array C[ii][jj] -> Buffer C(jj, ii)
                std::cerr << C(jj, ii) << '\n';
            }
        }
    }

    std::cout << std::fixed << std::setprecision(6);
    std::cout << duration.count() << std::endl;

    return 0;
}
